sections.Installation:
```bash
npm install @dillingerstaffing/strand @dillingerstaffing/strand-ui
```

Import the design tokens and component styles in your app entry:

```css
@import '@dillingerstaffing/strand/css/reset.css';
@import '@dillingerstaffing/strand/css/tokens.css';
@import '@dillingerstaffing/strand/css/base.css';
@import '@dillingerstaffing/strand-ui/css/strand-ui.css';
```

sections.Example:
```jsx
import { Button, Card, Stack, Input } from '@dillingerstaffing/strand-ui';

export function App() {
  return (
    <Card variant="elevated" padding="lg">
      <Stack gap={4}>
        <Input placeholder="Enter your email" />
        <Button>Get Started</Button>
      </Stack>
    </Card>
  );
}
```

```js
import VisualController from '@peter.naydenov/visual-controller-for-preact';
import HeaderApp from './apps/header.jsx';
import SidebarApp from './apps/sidebar.jsx';
import CartApp from './apps/cart.jsx';

const html = new VisualController({});

html.set(({ start, end }) => {
  document.querySelector('header').append(start, end);
  return 'header';
});

html.set(({ start, end }) => {
  document.querySelector('aside').append(start, end);
  return 'sidebar';
});

html.set(({ start, end }) => {
  document.querySelector('main').append(start, end);
  return 'cart';
});

html.publish('header', HeaderApp);
html.publish('sidebar', SidebarApp);
html.publish('cart', CartApp);
```

